runs.command:
seen = []
for label in (NATURAL, "(amu * angstrom^2 / eV)^0.5"):
    meta = {**LABELLED_FS, "units": {**LABELLED_FS["units"], "time": label}}
    del meta["validate"]
    frames = quiet(lambda: readcon.read_con_string(replaced_line2(TINY_VEL, meta)))
    write = raised(lambda: readcon.write_con_string(frames))
    to_ase = raised(lambda: frames[0].to_ase())
    seen.append((label, frames[0].velocity_time_unit, str(write), str(to_ase)))
return ("; ".join(f"{label}: velocity_time_unit {u!r}, write {w}, to_ase {a}" for label, u, w, a in seen),
        all(u == NATURAL and w == a == "no error" for _, u, w, a in seen))

seen = {}
for name, meta in (("declared", '{"con_spec_version":2,"pbc":[true,false,true]}'),
                   ("absent", '{"con_spec_version":2}')):
    frame = readcon.read_con_string(cu_frame(meta))[0]
    seen[name] = (tuple(frame.pbc), tuple(bool(x) for x in quiet(lambda: frame.to_ase().pbc)))
return "; ".join(f"{name}: ConFrame.pbc {a}, to_ase().pbc {b}" for name, (a, b) in seen.items()), (
    seen == {"declared": ((True, False, True),) * 2, "absent": ((True, True, True),) * 2})

seen = {}
for minor in (2, 7):
    frames = readcon.read_con_string(two_atom_frame({"con_spec_version": 3, "con_spec_minor": minor, "units": UN},
                                                    rows=("0.0 0.0 0.0 0", "1.0 1.0 1.0 0")))
    seen[minor] = frames[0].atom_ids_array().tolist()
return "; ".join(f"minor {m}: ids {ids}" for m, ids in seen.items()), seen == {2: [0, 1], 7: [0, 1]}

text = EMPTY_SECTIONS_VELOCITY_H
calls = {"1 copy": lambda: readcon.read_con_string(text),
         "300 copies": lambda: readcon.read_con_string(text * 300),
         "300 copies, n_threads=1": lambda: readcon.read_con_string(text * 300, n_threads=1),
         "300 copies, n_threads=4": lambda: readcon.read_con_string(text * 300, n_threads=4)}
seen = {name: verdict(fn) for name, fn in calls.items()}
want = rejects("InvalidNumberFormat", line=15)
written(tmp, "x300.con", text * 300)
where = {"readcon-core": cli_read(tmp, "x300.con"), "indep_reader": read("indep_reader", text * 300, tmp)}
answers = set(seen.values())
return (f"{one_answer(seen)}; " + "; ".join(f"{r}: {described(g)}" for r, g in where.items()),
        len(answers) == 1 and answers.pop().startswith("reject InvalidNumberFormat:")
        and all(want.met(r, g) for r, g in where.items()))
